\lim_{{n} \to {\infty}} \sin(x)^{n} &= \lim_{{n} \to {\infty}} \mathrm{e}^{\ln(\sin(x)^{n})}\\
\lim_{{n} \to {\infty}} \sin(x)^{n} &= \lim_{{n} \to {\infty}} \mathrm{e}^{n \cdot \ln(\sin(x))}\\
