\lim_{{n} \to {\infty}} \sin(x)^{n} &= 
0\\
F(x) = \int_{0}^{x} \lim_{{n} \to {\infty}} \sin(x)^{n} ~\operatorname{d}x &= \int_{0}^{x} \lim_{{n} \to {\infty}} 0 ~\operatorname{d}x \\
